impl core::fmt::Debug for ExportDef<'_> {
  fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
    let mut ds = f.debug_struct("ExportDef");
      ds.field("name", &self.name());
      ds.field("kernel_type", &self.kernel_type());
      match self.kernel_type() {
        KernelDef::Conv2DDef => {
          if let Some(x) = self.kernel_as_conv_2ddef() {
            ds.field("kernel", &x)
          } else {
            ds.field("kernel", &"InvalidFlatbuffer: Union discriminant does not match value.")
          }
        },
        KernelDef::FullyConnectedDef => {
          if let Some(x) = self.kernel_as_fully_connected_def() {
            ds.field("kernel", &x)
          } else {
            ds.field("kernel", &"InvalidFlatbuffer: Union discriminant does not match value.")
          }
        },
        _ => {
          let x: Option<()> = None;
          ds.field("kernel", &x)
        },
      };
      ds.finish()
  }
}
